<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Branch;use App\Models\City;use App\Models\CourseType;use App\Models\TheoryCourse;use App\Models\TheoryCoursePage;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;use Illuminate\View\View;
class TheoryCourseController extends Controller {public function index():View{return view('admin.theory-courses.index',['courses'=>TheoryCourse::with(['type','city','branch'])->orderBy('sort_order')->paginate(20),'settings'=>TheoryCoursePage::firstOrCreate([])]);}public function create():View{return view('admin.theory-courses.form',$this->options()+['course'=>new TheoryCourse,'editing'=>false]);}public function store(Request $r):RedirectResponse{$data=$this->validated($r);$data['slug']=$this->slug($data['title']);if($r->hasFile('image'))$data['image']=$r->file('image')->store('theory-courses','public');$data['is_active']=$r->boolean('is_active');TheoryCourse::create($data);return redirect()->route('admin.theory-courses.index')->with('status','Theory course created successfully.');}public function edit(TheoryCourse $theoryCourse):View{return view('admin.theory-courses.form',$this->options()+['course'=>$theoryCourse,'editing'=>true]);}public function update(Request $r,TheoryCourse $theoryCourse):RedirectResponse{$data=$this->validated($r);if($data['title']!==$theoryCourse->title)$data['slug']=$this->slug($data['title'],$theoryCourse->id);if($r->hasFile('image')){if($theoryCourse->image)Storage::disk('public')->delete($theoryCourse->image);$data['image']=$r->file('image')->store('theory-courses','public');}$data['is_active']=$r->boolean('is_active');$theoryCourse->update($data);return redirect()->route('admin.theory-courses.index')->with('status','Theory course updated successfully.');}public function destroy(TheoryCourse $theoryCourse):RedirectResponse{if($theoryCourse->image)Storage::disk('public')->delete($theoryCourse->image);$theoryCourse->delete();return back()->with('status','Theory course deleted successfully.');}public function settings(Request $r):RedirectResponse{$data=$r->validate(['page_title'=>['required','string','max:255'],'category_title'=>['required','string','max:255'],'faq_title'=>['required','string','max:255'],'faq_image'=>['nullable','image','max:10240']]);$s=TheoryCoursePage::firstOrCreate([]);if($r->hasFile('faq_image')){if($s->faq_image)Storage::disk('public')->delete($s->faq_image);$data['faq_image']=$r->file('faq_image')->store('theory-courses','public');}else unset($data['faq_image']);$s->update($data);return back()->with('status','Theory course page settings updated.');}private function options():array{return['types'=>CourseType::where('is_active',true)->orderBy('name')->get(),'cities'=>City::where('is_active',true)->orderBy('name')->get(),'branches'=>Branch::where('is_active',true)->orderBy('name')->get()];}private function validated(Request $r):array{return $r->validate(['course_type_id'=>['required','exists:course_types,id'],'city_id'=>['required','exists:cities,id'],'branch_id'=>['required','exists:branches,id'],'title'=>['required','string','max:255'],'fee'=>['required','numeric','min:0'],'duration'=>['nullable','string','max:100'],'discount'=>['nullable','integer','between:0,100'],'description'=>['nullable','string'],'image'=>['nullable','image','max:4096'],'sort_order'=>['nullable','integer','min:0']]);}private function slug(string $title,?int $ignore=null):string{$base=Str::slug($title)?:'theory-course';$slug=$base;$i=2;while(TheoryCourse::where('slug',$slug)->when($ignore,fn($q)=>$q->whereKeyNot($ignore))->exists())$slug=$base.'-'.$i++;return $slug;}}
